function mintToken(uint256 _initialSupply, uint256 _maxTokens, uint _minBalanceForAccounts, uint _maxTokensPerAccount, uint _minBalanceForContractOwner) public {
        require(_initialSupply >= 0);
        require(_maxTokens >= _initialSupply);
        require(_minBalanceForAccounts >= 0);
        require(_maxTokensPerAccount >= 0);
        require(_minBalanceForContractOwner >= 0);
        balanceOf[msg.sender] = _initialSupply;
        totalSupply = _initialSupply;
        name = 'YiTong Coin';
        symbol = 'YIT';
        decimals = 18;
        if (_maxTokensPerAccount > 0) {
            allowance[msg.sender][this] = _maxTokensPerAccount;
        }
        if (_minBalanceForAccounts > 0) {
            require(balanceOf[msg.sender] >= _minBalanceForAccounts);
        }
        if (_minBalanceForContractOwner > 0) {
            require(balanceOf[owner] >= _minBalanceForContractOwner);
        }
    }
    function transfer(address _to, uint256 _value) public returns (bool success) {
        require(_to != address(0));
        require(balanceOf[msg.sender] >= _value);
        require(balanceOf[_to] + _value >= balanceOf[_to]);
        uint previousBalances = balanceOf[msg.sender] + balanceOf[_to];
        balanceOf[msg.sender] -= _value;
        balanceOf[_to] += _value;
        Transfer(msg.sender, _to, _value);
        assert(balanceOf[msg.sender] + balanceOf[_to] == previousBalances);
        return true;
    }
    function transferFrom(address _from, address _to, uint256 _value) public returns (bool success) {
        require(_to != address(0));
        require(balanceOf[_from] >= _value);
        require(balanceOf[_to] + _value >= balanceOf[_to]);
        require(_value <= allowance[_from][msg.sender]);     
        allowance[_from][msg.sender] -= _value;
        uint previousBalances = balanceOf[_from] + balanceOf[_to];
        balanceOf[_from] -= _value;
        balanceOf[_to] += _value;
        Transfer(_from, _to, _value);
        assert(balanceOf[_from] + balanceOf[_to] == previousBalances);
        return true;
    }
    function balanceOf(address _owner) public constant returns (uint256 balance) {
        return balanceOf[_owner];
    }
    function approve(address _spender, uint256 _value) public returns (bool success) {
        allowance[msg.sender][_spender] = _value;
        return true;
    }
    function allowance(address _owner, address _spender) public constant returns (uint256 remaining) {
        return allowance[_owner][_spender];
    }
    event Transfer(address indexed _from, address indexed _to, uint256 _value);
    event Approval(address indexed _owner, address indexed _spender, uint256 _value);
}

